const Advertisment=require("../models/advertismentModel"),handleErrors=require("../utilities/handle_errors")["handleErrors"],create_advertisment=async(t,s,e)=>{Advertisment.findOne({priority:t.body.priority,status:"active",advertiseAt:t.body.advertiseAt}).then(e=>{Advertisment.create(t.body).then(e=>{s.status(200).send(e)}).catch(e=>{s.status(422).send(handleErrors(e,t,"advertisment"))})})},get_advertisment=(e,i,t)=>{e=(e.query.page||1)-1;const a=100;e*=a;Advertisment.aggregate([{$skip:e},{$sample:{size:a}},{$limit:a}]).then(async e=>{var t=await Advertisment.countDocuments(),s=e.filter(e=>"bestOffers"==e.advertiseAt),d=e.filter(e=>"websitePages"==e.advertiseAt),e=e.filter(e=>"videoAds"==e.advertiseAt);i.status(200).send({advertisments:d,bestOffers:s,videoAds:e,total_advertisments:t,per_page:a})}).catch(e=>{t(e)})},get_admin_advertisments=(e,t,s)=>{Advertisment.find({company:{$regex:e.query.company,$options:"i"}}).then(async e=>{t.status(200).send({advertisments:e})}).catch(e=>{s(e)})},get_single_advertisment=(e,t,s)=>{Advertisment.findById({_id:e.params.id}).then(e=>t.status(200).send(e)).catch(s)},delete_advertisment=(e,t,s)=>{Advertisment.findByIdAndDelete({_id:e.params.id}).then(e=>{t.status(200).send(e)}).catch(s)},update_advertisment=(t,s,e)=>{Advertisment.findByIdAndUpdate({_id:t.params.id},t.body).then(e=>{Advertisment.findOne({_id:t.params.id}).then(e=>s.status(200).send(e))}).catch(e)},ad_clicked=(e,t,s)=>{Advertisment.findByIdAndUpdate({_id:e.params.id},{$inc:{clicks:1}}).then(e=>t.status(200).send(e)).catch(s)};module.exports={create_advertisment:create_advertisment,get_advertisment:get_advertisment,get_single_advertisment:get_single_advertisment,delete_advertisment:delete_advertisment,update_advertisment:update_advertisment,ad_clicked:ad_clicked,get_admin_advertisments:get_admin_advertisments};